/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

export type EventRsvp = "accepted" | "tentative" | "declined"

export interface EventAttendee {
  name: string
  email?: string
  avatar?: string
  /** Their reply. Missing means they have not answered. */
  status?: EventRsvp | "pending"
  organizer?: boolean
}

export type EventCardStatus = "confirmed" | "tentative" | "cancelled"

export interface EventConflict {
  title: string
  /** Display time of the other event: "14:30 to 15:00". */
  time?: string
}

type CalendarProvider = "google" | "outlook" | "ics"

/**
 * Calendar helpers for event cards: links that open a prefilled event in Google Calendar or
 * Outlook, and an RFC 5545 .ics file for everything else (Apple Calendar, Fastmail, Thunderbird).
 * Pure functions, no dependencies, safe on the server.
 */

interface CalendarEventInput {
  title: string
  /** ISO string, epoch ms or Date. */
  start: string | number | Date
  /** Defaults to one hour after `start` (or one day for all-day events). */
  end?: string | number | Date
  allDay?: boolean
  location?: string
  /** Plain text. A video link is appended to it when given. */
  description?: string
  videoUrl?: string
  /** Stable id so re-importing the file updates the event instead of duplicating it. */
  uid?: string
  organizer?: { name?: string; email: string }
}

/** Every string the card writes itself, for translation. Dates and times follow `locale`. */
export interface EventCardLabels {
  going: string
  accept: string
  maybe: string
  decline: string
  addToCalendar: string
  overlapsWith: string
  join: string
  /** Joins two times: "14:00 to 14:45". */
  to: string
  allDay: string
  guests: (total: number, going: number) => string
}

export interface EventCardProps extends Omit<React.ComponentProps<"div">, "title" | "children"> {
  title?: string
  /** ISO string with offset, epoch ms or Date. */
  start?: string | number | Date
  end?: string | number | Date
  allDay?: boolean
  /** IANA zone the times are shown in, for example "Europe/Lisbon". Defaults to the viewer's. */
  timeZone?: string
  /** A second zone to show the same times in, for example the organizer's. */
  secondaryTimeZone?: string
  /** Name for the second zone: "Lisbon". Defaults to the zone's short name. */
  secondaryTimeZoneLabel?: string
  locale?: string
  /** Force a 12 or 24 hour clock. Defaults to the locale's. */
  hour12?: boolean
  location?: string
  /** Opens maps for `location`. */
  locationHref?: string
  videoUrl?: string
  /** "Google Meet", "Zoom". Shown on the join row. */
  videoLabel?: string
  description?: string
  /** The calendar it lands in: "Work". */
  calendar?: string
  attendees?: EventAttendee[]
  /** Avatars before the +N chip. Default 4. */
  maxAvatars?: number
  status?: EventCardStatus
  /** Controlled reply. */
  rsvp?: EventRsvp | null
  defaultRsvp?: EventRsvp | null
  /** Return a promise to show progress; a rejection rolls the reply back and shows an error. */
  onRsvpChange?: (rsvp: EventRsvp) => unknown | Promise<unknown>
  /** Other events in the same slot. Shows the amber overlap note. */
  conflicts?: EventConflict[]
  /** Show the Add to calendar menu. Default true. */
  addToCalendar?: boolean
  /** Runs before the default action. Return `false` to handle it yourself. */
  onAddToCalendar?: (provider: CalendarProvider, event: CalendarEventInput) => undefined | boolean
  onJoin?: () => void
  layout?: "full" | "compact"
  labels?: Partial<EventCardLabels>
  loading?: boolean
  error?: React.ReactNode
  onRetry?: () => void
  /** Shown when there is no event, for example a free slot search that found nothing. */
  empty?: React.ReactNode
}

const DEFAULT_LABELS: EventCardLabels = {
  going: "Going?",
  accept: "Accept",
  maybe: "Maybe",
  decline: "Decline",
  addToCalendar: "Add to calendar",
  overlapsWith: "Overlaps with",
  join: "Join",
  to: "to",
  allDay: "All day",
  guests: (total, going) =>
    `${total} ${total === 1 ? "guest" : "guests"}${going ? `, ${going} going` : ""}`,
}

interface EventTimes {
  tileMonth: string
  tileDay: string
  date: string
  time: string
  duration?: string
  zone?: string
  secondary?: string
}

/* -------------------------------------------------------------------------------------------------
 * Formatting
 * -----------------------------------------------------------------------------------------------*/

const toDate = (v: string | number | Date) => (v instanceof Date ? v : new Date(v))

function zoneName(date: Date, locale: string, timeZone?: string) {
  try {
    return new Intl.DateTimeFormat(locale, { timeZone, timeZoneName: "short" })
      .formatToParts(date)
      .find((p) => p.type === "timeZoneName")?.value
  } catch {
    return undefined
  }
}

function formatDuration(minutes: number) {
  if (minutes < 60) return `${minutes} min`
  const h = Math.floor(minutes / 60)
  const m = minutes % 60
  return m ? `${h} h ${m} min` : `${h} h`
}

function useEventTimes({
  start,
  end,
  allDay,
  timeZone,
  secondaryTimeZone,
  secondaryTimeZoneLabel,
  locale,
  hour12,
  to = "to",
  allDayLabel = "All day",
}: { to?: string; allDayLabel?: string } & Pick<
  EventCardProps,
  | "start"
  | "end"
  | "allDay"
  | "timeZone"
  | "secondaryTimeZone"
  | "secondaryTimeZoneLabel"
  | "locale"
  | "hour12"
>): EventTimes | null {
  return React.useMemo(() => {
    if (start === undefined) return null
    const s = toDate(start)
    if (Number.isNaN(s.getTime())) return null
    const e = end !== undefined ? toDate(end) : undefined
    const loc = locale ?? "en-US"
    const tz = { timeZone }
    const day = (d: Date) =>
      new Intl.DateTimeFormat(loc, {
        ...tz,
        weekday: "short",
        month: "short",
        day: "numeric",
      }).format(d)
    const clock = (d: Date, zone?: string) =>
      new Intl.DateTimeFormat(loc, {
        timeZone: zone ?? timeZone,
        hour: "numeric",
        minute: "2-digit",
        ...(hour12 !== undefined ? { hour12 } : {}),
      }).format(d)
    const sameDay = (a: Date, b: Date) =>
      new Intl.DateTimeFormat("en-CA", { ...tz, dateStyle: "short" }).format(a) ===
      new Intl.DateTimeFormat("en-CA", { ...tz, dateStyle: "short" }).format(b)

    const minutes = e ? Math.round((e.getTime() - s.getTime()) / 60_000) : undefined
    const multiDay = e ? !sameDay(s, allDay ? new Date(e.getTime() - 1) : e) : false
    let time: string
    if (allDay)
      time = multiDay && e ? `${allDayLabel}, ${to} ${day(new Date(e.getTime() - 1))}` : allDayLabel
    else if (e && multiDay) time = `${clock(s)} ${to} ${day(e)}, ${clock(e)}`
    else time = e ? `${clock(s)} ${to} ${clock(e)}` : clock(s)

    let secondary: string | undefined
    if (!allDay && secondaryTimeZone && secondaryTimeZone !== timeZone) {
      const label =
        secondaryTimeZoneLabel ?? zoneName(s, loc, secondaryTimeZone) ?? secondaryTimeZone
      const range = e
        ? `${clock(s, secondaryTimeZone)} ${to} ${clock(e, secondaryTimeZone)}`
        : clock(s, secondaryTimeZone)
      secondary = `${range} in ${label}`
    }

    return {
      tileMonth: new Intl.DateTimeFormat(loc, { ...tz, month: "short" }).format(s),
      tileDay: new Intl.DateTimeFormat(loc, { ...tz, day: "numeric" }).format(s),
      date: day(s),
      time,
      duration:
        !allDay && minutes !== undefined && minutes > 0 && !multiDay
          ? formatDuration(minutes)
          : undefined,
      zone: allDay ? undefined : zoneName(s, loc, timeZone),
      secondary,
    }
  }, [
    start,
    end,
    allDay,
    timeZone,
    secondaryTimeZone,
    secondaryTimeZoneLabel,
    locale,
    hour12,
    to,
    allDayLabel,
  ])
}

