/** A calendar leaf: the month above the day, so the date reads before the title. */
function DateTile({ month, day, compact }: { month: string; day: string; compact?: boolean }) {
  return (
    <span
      aria-hidden="true"
      className={cn(
        "bg-(color:--chatcn-fill) rounded-(--chatcn-radius-md) flex shrink-0 flex-col items-center justify-center leading-none",
        compact ? "size-10 gap-0.5" : "size-12 gap-1",
      )}
    >
      <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle)">{month}</span>
      <span
        className={cn(
          "text-(color:--chatcn-fg) font-medium tabular-nums",
          compact ? "text-[0.9375rem]/[1.5rem] tracking-[-0.006em]" : "text-[1.125rem]/[1.625rem] tracking-[-0.015em]",
        )}
      >
        {day}
      </span>
    </span>
  )
}

