const toDate2 = (value: string | number | Date) => (value instanceof Date ? value : new Date(value))

const HOUR = 3_600_000

const DAY = 24 * HOUR

function range(event: CalendarEventInput) {
  const start = toDate2(event.start)
  const end = event.end
    ? toDate2(event.end)
    : new Date(start.getTime() + (event.allDay ? DAY : HOUR))
  return { start, end }
}

const pad = (n: number) => String(n).padStart(2, "0")

/** 20261106T140000Z, the UTC form every provider accepts. */
function utcStamp(d: Date) {
  return `${d.getUTCFullYear()}${pad(d.getUTCMonth() + 1)}${pad(d.getUTCDate())}T${pad(d.getUTCHours())}${pad(d.getUTCMinutes())}${pad(d.getUTCSeconds())}Z`
}

/** A short stable hash so the default UID does not change between downloads. */
function hash(value: string) {
  let h = 0
  for (let i = 0; i < value.length; i++) h = (Math.imul(31, h) + value.charCodeAt(i)) | 0
  return (h >>> 0).toString(36)
}

/** 20261106, for all-day events. Uses the UTC date so a midnight ISO string stays on its day. */
function dateStamp(d: Date) {
  return `${d.getUTCFullYear()}${pad(d.getUTCMonth() + 1)}${pad(d.getUTCDate())}`
}

/** Escapes text values per RFC 5545 section 3.3.11. */
function escapeText(value: string) {
  return value
    .replace(/\\/g, "\\\\")
    .replace(/;/g, "\\;")
    .replace(/,/g, "\\,")
    .replace(/\r?\n/g, "\\n")
}

function details(event: CalendarEventInput) {
  return [event.description, event.videoUrl ? `Join: ${event.videoUrl}` : undefined]
    .filter(Boolean)
    .join("\n\n")
}

/** Folds content lines at 75 octets, continuing with a leading space (RFC 5545 section 3.1). */
function fold(line: string) {
  const bytes = new TextEncoder()
  if (bytes.encode(line).length <= 75) return line
  const parts: string[] = []
  let current = ""
  for (const char of line) {
    const limit = parts.length === 0 ? 75 : 74
    if (bytes.encode(current + char).length > limit) {
      parts.push(current)
      current = char
    } else {
      current += char
    }
  }
  parts.push(current)
  return parts.join("\r\n ")
}

/** A single-event VCALENDAR document. Times are written in UTC, so no VTIMEZONE is needed. */
function buildIcs(event: CalendarEventInput, now: Date = new Date()) {
  const { start, end } = range(event)
  const uid = event.uid ?? `${utcStamp(start)}-${hash(event.title)}@chatcn`
  const lines = [
    "BEGIN:VCALENDAR",
    "VERSION:2.0",
    "PRODID:-//chatcn//event-card//EN",
    "CALSCALE:GREGORIAN",
    "METHOD:PUBLISH",
    "BEGIN:VEVENT",
    `UID:${uid}`,
    `DTSTAMP:${utcStamp(now)}`,
    event.allDay ? `DTSTART;VALUE=DATE:${dateStamp(start)}` : `DTSTART:${utcStamp(start)}`,
    event.allDay ? `DTEND;VALUE=DATE:${dateStamp(end)}` : `DTEND:${utcStamp(end)}`,
    `SUMMARY:${escapeText(event.title)}`,
  ]
  const body = details(event)
  if (body) lines.push(`DESCRIPTION:${escapeText(body)}`)
  if (event.location) lines.push(`LOCATION:${escapeText(event.location)}`)
  if (event.videoUrl) lines.push(`URL:${event.videoUrl}`)
  if (event.organizer) {
    const cn = event.organizer.name ? `;CN=${escapeText(event.organizer.name)}` : ""
    lines.push(`ORGANIZER${cn}:mailto:${event.organizer.email}`)
  }
  lines.push("END:VEVENT", "END:VCALENDAR")
  return `${lines.map(fold).join("\r\n")}\r\n`
}

/** A file name that survives every OS: "design-review-2026-11-06.ics". */
function icsFileName(event: CalendarEventInput) {
  const slug =
    event.title
      .toLowerCase()
      .normalize("NFKD")
      .replace(/[^\p{L}\p{N}]+/gu, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 48) || "event"
  return `${slug}-${range(event).start.toISOString().slice(0, 10)}.ics`
}

/** Browser only: saves the .ics file through a temporary object URL. */
function downloadIcs(event: CalendarEventInput) {
  const blob = new Blob([buildIcs(event)], { type: "text/calendar;charset=utf-8" })
  const url = URL.createObjectURL(blob)
  const a = document.createElement("a")
  a.href = url
  a.download = icsFileName(event)
  document.body.appendChild(a)
  a.click()
  a.remove()
  window.setTimeout(() => URL.revokeObjectURL(url), 1000)
}

/** Opens Google Calendar's new event screen with every field filled in. */
function googleCalendarUrl(event: CalendarEventInput) {
  const { start, end } = range(event)
  const dates = event.allDay
    ? `${dateStamp(start)}/${dateStamp(end)}`
    : `${utcStamp(start)}/${utcStamp(end)}`
  const params = new URLSearchParams({ action: "TEMPLATE", text: event.title, dates })
  const body = details(event)
  if (body) params.set("details", body)
  if (event.location) params.set("location", event.location)
  return `https://calendar.google.com/calendar/render?${params.toString()}`
}

/** Opens Outlook on the web (personal and work accounts share this deep link). */
function outlookCalendarUrl(event: CalendarEventInput) {
  const { start, end } = range(event)
  const params = new URLSearchParams({
    path: "/calendar/action/compose",
    rru: "addevent",
    subject: event.title,
    startdt: event.allDay ? start.toISOString().slice(0, 10) : start.toISOString(),
    enddt: event.allDay ? end.toISOString().slice(0, 10) : end.toISOString(),
  })
  if (event.allDay) params.set("allday", "true")
  const body = details(event)
  if (body) params.set("body", body)
  if (event.location) params.set("location", event.location)
  return `https://outlook.live.com/calendar/0/action/compose?${params.toString()}`
}

