  videoLabel = "Video call",
  description,
  calendar,
  attendees,
  maxAvatars = 4,
  status = "confirmed",
  rsvp: rsvpProp,
  defaultRsvp = null,
  onRsvpChange,
  conflicts,
  addToCalendar = true,
  onAddToCalendar,
  onJoin,
  layout = "full",
  labels: labelsProp,
  loading = false,
  error,
  onRetry,
  empty,
  className,
  ...props
}: EventCardProps) {
  const [rsvpState, setRsvpState] = React.useState<EventRsvp | null>(defaultRsvp)
  const [pending, setPending] = React.useState<EventRsvp | null>(null)
  const [rsvpError, setRsvpError] = React.useState<string | null>(null)
  const rsvp = pending ?? (rsvpProp !== undefined ? rsvpProp : rsvpState)
  const labels = { ...DEFAULT_LABELS, ...labelsProp }
  const times = useEventTimes({
    to: labels.to,
    allDayLabel: labels.allDay,
    start,
    end,
    allDay,
    timeZone,
    secondaryTimeZone,
    secondaryTimeZoneLabel,
    locale,
    hour12,
  })
  const compact = layout === "compact"
  const cancelled = status === "cancelled"
  const people = (attendees ?? []).filter((a) => a?.name)
  const overlaps = (conflicts ?? []).filter((c) => c?.title)

  const reply = async (next: EventRsvp) => {
    if (next === rsvp || pending) return
    const previous = rsvp
    setRsvpError(null)
    setRsvpState(next)
    const result = onRsvpChange?.(next)
    if (!(result instanceof Promise)) return
    setPending(next)
    try {
      await result
    } catch {
      setRsvpState(previous)
      setRsvpError("Your reply was not sent. Check your connection, then choose again.")
    } finally {
      setPending(null)
    }
  }

  if (error) {
    return (
      <div
        data-slot="event-card"
        data-event-state="error"
        role="alert"
        className={cn(surface, "gap-2 p-4", className)}
        {...props}
      >
        <div className="flex items-center gap-2">
          <CircleAlertIcon aria-hidden="true" className="text-(color:--chatcn-red) size-4 shrink-0" />
          <span className="font-medium">Event unavailable</span>
        </div>
        <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) ps-6 text-pretty">{error}</p>
        {onRetry ? (
          <Button size="sm" variant="outline" className="ms-6 self-start" onClick={onRetry}>
            <RotateCcwIcon />
            Try again
          </Button>
        ) : null}
      </div>
    )
  }

  if (loading) {
    return (
      <div
        data-slot="event-card"
        data-event-state="loading"
        aria-busy="true"
        className={cn(surface, className)}
        {...props}
      >
        <span className="sr-only">Loading event</span>
        <div aria-hidden="true" className={cn("flex items-center gap-3", compact ? "p-3" : "p-4")}>
          <span
            className={cn(
              "bg-(color:--chatcn-fill) rounded-(--chatcn-radius-md) shrink-0",
              compact ? "size-10" : "size-12",
            )}
          />
          <span className="flex flex-1 flex-col gap-2">
            <span className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-xs) h-3.5 w-2/5" />
            <span className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-xs) h-3 w-3/5" />
          </span>
        </div>
        {compact ? null : (
          <>
            <div aria-hidden="true" className="flex flex-col gap-3 px-4 pb-4">
              {["w-1/2", "w-1/3", "w-2/5"].map((w) => (
                <span key={w} className="flex items-center gap-3">
                  <span className="grid w-12 place-items-center">
                    <span className="bg-(color:--chatcn-fill) size-4 rounded-full" />
                  </span>
                  <span className={cn("bg-(color:--chatcn-fill) rounded-(--chatcn-radius-xs) h-3", w)} />
                </span>
              ))}
            </div>
            <div
              aria-hidden="true"
              className="border-(color:--chatcn-border) flex items-center justify-between border-t px-4 py-3"
            >
              <span className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-md) h-8 w-56" />
              <span className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-sm) h-7 w-32" />
            </div>
          </>
        )}
      </div>
    )
  }

  if (!title || !times) {
    return (
      <div
        data-slot="event-card"
        data-event-state="empty"
        className={cn(surface, "flex-row items-start gap-3 p-4", className)}
        {...props}
      >
        <CalendarPlusIcon
          aria-hidden="true"
          className="text-(color:--chatcn-fg-subtle) mt-0.5 size-4 shrink-0"
        />
        <div className="flex flex-col gap-0.5">
          <span className="font-medium">No event found</span>
          <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) text-pretty">
            {empty ?? "Nothing matched that time. Ask for a different day or a wider window."}
          </span>
        </div>
      </div>
    )
  }

  const calendarEvent: CalendarEventInput = {
    title,
    start: start as string | number | Date,
    end,
    allDay,
    location,
    description,
    videoUrl,
  }
  const organizer = people.find((a) => a.organizer)

  const statusLabel = cancelled ? (
    <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-red) flex shrink-0 items-center gap-1">
      <BanIcon aria-hidden="true" className="size-3.5" />
      Cancelled
    </span>
  ) : status === "tentative" ? (
    <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) shrink-0">Tentative</span>
  ) : null

  const overlapNote =
    overlaps.length > 0 && !cancelled ? (
      <p
        className={cn(
          "text-[0.8125rem]/[1.25rem] bg-(color:--chatcn-amber-bg) text-(color:--chatcn-amber) rounded-(--chatcn-radius-md) flex items-start gap-2 px-2.5 py-2",
        )}
      >
        <TriangleAlertIcon aria-hidden="true" className="mt-0.5 size-3.5 shrink-0" />
        <span className="min-w-0 text-pretty">
          {labels.overlapsWith} <span className="font-medium">{overlaps[0]?.title}</span>
          {overlaps[0]?.time ? <span className="tabular-nums">, {overlaps[0].time}</span> : null}
          {overlaps.length > 1 ? ` and ${overlaps.length - 1} more` : null}
        </span>
      </p>
    ) : null

  const timeLine = (
    <span className="tabular-nums">
      {times.date}
      <span aria-hidden="true"> · </span>
      <span className="sr-only">, </span>
      {times.time}
      {times.duration ? (
        // A duration never splits across lines ("45" on one line, "min" on the next).
        <span className="text-(color:--chatcn-fg-subtle) whitespace-nowrap"> ({times.duration})</span>
      ) : null}
      {times.zone ? <span className="text-(color:--chatcn-fg-subtle)"> {times.zone}</span> : null}
    </span>
  )

  if (compact) {
    return (
      <div
        data-slot="event-card"
        data-event-state={cancelled ? "cancelled" : "ready"}
        data-layout="compact"
        className={cn(surface, "flex-row items-center gap-3 p-3", className)}
        {...props}
      >
        <DateTile month={times.tileMonth} day={times.tileDay} compact />
        <div className="flex min-w-0 flex-1 flex-col gap-0.5">
          <span className="flex min-w-0 items-center gap-2">
            <span
              className={cn("min-w-0 truncate font-medium", cancelled && "text-(color:--chatcn-fg-muted)")}
            >
              {title}
            </span>
            {overlaps.length > 0 && !cancelled ? (
              <span className="text-(color:--chatcn-amber) flex shrink-0 items-center gap-1">
                <TriangleAlertIcon aria-hidden="true" className="size-3.5" />
                <span className="text-[0.75rem]/[1rem]">Overlap</span>
              </span>
            ) : null}
            {statusLabel}
          </span>
          <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) truncate">
            {timeLine}
            {location ? (
              <span className="text-(color:--chatcn-fg-subtle)">
                <span aria-hidden="true"> · </span>
                {location}
              </span>
            ) : null}
          </span>
        </div>
        {rsvp && !cancelled ? (
          <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) hidden shrink-0 items-center gap-1 sm:flex">
            {STATUS_ICON[rsvp]}
            {RSVP_WORDS[rsvp]}
          </span>
        ) : null}
        {videoUrl && !cancelled ? (
          <a
            href={videoUrl}
            target="_blank"
            rel="noreferrer"
            onClick={onJoin}
            className={cn(
              "chatcn-focus rounded-(--chatcn-radius-sm) text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg) bg-(color:--chatcn-fill) hover:bg-(color:--chatcn-fill-hover) inline-flex h-7 shrink-0 items-center gap-1.5 px-2.5 font-medium",
              "ease-(--chatcn-ease-standard) transition-[background-color,scale] duration-150 active:scale-(--chatcn-press-scale) active:duration-100 pointer-coarse:h-11",
            )}
          >
            <VideoIcon aria-hidden="true" className="size-3.5" />
            {labels.join}
          </a>
        ) : null}
        {addToCalendar && !cancelled ? (
          <AddToCalendar
            event={calendarEvent}
            onAddToCalendar={onAddToCalendar}
            label={labels.addToCalendar}
            iconOnly
          />
        ) : null}
      </div>
    )
  }

  return (
    <div
      data-slot="event-card"
      data-event-state={cancelled ? "cancelled" : "ready"}
      data-layout="full"
      className={cn(surface, className)}
      {...props}
    >
      {/* When */}
      <div className="flex items-start gap-3 p-4 pb-3">
        <DateTile month={times.tileMonth} day={times.tileDay} />
        <div className="flex min-w-0 flex-1 flex-col gap-1 pt-0.5">
          <div className="flex items-start justify-between gap-3">
            <h3
              className={cn(
                "text-[0.9375rem]/[1.5rem] tracking-[-0.006em] font-medium tracking-tight text-balance",
                cancelled && "text-(color:--chatcn-fg-muted)",
              )}
            >
              {title}
            </h3>
            {statusLabel}
          </div>
          <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted)">{timeLine}</p>
          {times.secondary ? (
            <p className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) tabular-nums">{times.secondary}</p>
          ) : null}
        </div>
      </div>

      {/* Where and who */}
      {location || videoUrl || people.length || calendar || description || overlapNote ? (
        // Cancelled steps the text down the gray ramp and fades only pictures, so every line
        // stays readable.
        <div
          data-cancelled={cancelled ? "" : undefined}
          className={cn(
            "group/where flex flex-col gap-1 px-4 pb-3",
            cancelled && "[&_img]:opacity-60",
          )}
        >
          {videoUrl ? (
            <Row icon={<VideoIcon />}>
              <span className="min-w-0 truncate">
                {videoLabel}
                <span className="text-(color:--chatcn-fg-subtle)">
                  <span aria-hidden="true"> · </span>
                  {videoUrl.replace(/^https?:\/\//, "")}
                </span>
              </span>
              <a
                href={videoUrl}
                target="_blank"
                rel="noreferrer"
                onClick={onJoin}
                tabIndex={cancelled ? -1 : undefined}
                aria-disabled={cancelled || undefined}
                className={cn(
                  "chatcn-focus rounded-(--chatcn-radius-sm) text-[0.75rem]/[1rem] text-(color:--chatcn-fg) bg-(color:--chatcn-fill) hover:bg-(color:--chatcn-fill-hover) ms-auto inline-flex h-6 shrink-0 items-center px-2 font-medium",
                  "ease-(--chatcn-ease-standard) transition-[background-color,scale] duration-150 active:scale-(--chatcn-press-scale) active:duration-100 pointer-coarse:h-11",
                  cancelled && "pointer-events-none",
                )}
              >
                {labels.join}
              </a>
            </Row>
          ) : null}
          {location ? (
            <Row icon={<MapPinIcon />}>
              {locationHref ? (
                <a
                  href={locationHref}
                  target="_blank"
                  rel="noreferrer"
                  className="chatcn-focus hover:text-(color:--chatcn-fg) rounded-(--chatcn-radius-xs) line-clamp-2 text-pretty underline-offset-2 hover:underline"
                >
                  {location}
                </a>
              ) : (
                <span className="line-clamp-2 text-pretty">{location}</span>
              )}
            </Row>
          ) : null}
          {people.length ? (
            <Row icon={<UsersIcon />}>
              <Attendees attendees={people} max={maxAvatars} guests={labels.guests} />
            </Row>
          ) : null}
          {calendar ? (
            <Row icon={<span className="bg-(color:--chatcn-accent) size-2 rounded-[2px]" />}>
              <span className="truncate">
                {calendar}
                {organizer ? (
                  <span className="text-(color:--chatcn-fg-subtle)"> · Invited by {organizer.name}</span>
                ) : null}
              </span>
            </Row>
          ) : null}
          {description ? (
            <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) ms-15 line-clamp-3 pt-1 text-pretty">
              {description}
            </p>
          ) : null}
          {overlapNote ? <div className="ms-15 pt-2">{overlapNote}</div> : null}
        </div>
      ) : null}

      {/* Reply */}
      {cancelled ? (
        <p className="border-(color:--chatcn-border) text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) border-t px-4 py-3">
          {organizer ? `${organizer.name} cancelled this event.` : "This event was cancelled."}{" "}
          Nothing is needed from you.
        </p>
      ) : onRsvpChange || rsvpProp !== undefined || defaultRsvp || addToCalendar ? (
        <div className="border-(color:--chatcn-border) @container flex flex-wrap items-center gap-x-3 gap-y-2 border-t px-4 py-3">
          {onRsvpChange || rsvpProp !== undefined || defaultRsvp ? (
            // Narrow (a phone): the reply control fills the row and keeps the calendar button
            // beside it; the "Going?" prompt and the glyphs return once there is room.
            <div className="flex min-w-0 flex-1 items-center gap-3 @[26rem]:flex-none">
              <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) hidden @[26rem]:inline">
                {labels.going}
              </span>
              <ToggleGroup
                value={rsvp ? [rsvp] : []}
                onValueChange={(next) => {
                  const picked = next[0] as EventRsvp | undefined
                  if (picked) void reply(picked)
                }}
                aria-label="Your reply"
                className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-md) flex h-8 flex-1 items-center gap-0.5 p-0.5 @[26rem]:flex-none pointer-coarse:h-11"
              >
                {RSVP.map((option) => {
                  const Icon = option.icon
                  return (
                    <Toggle
                      key={option.value}
                      value={option.value}
                      disabled={pending !== null && pending !== option.value}
                      className={cn(
                        "group/rsvp chatcn-focus rounded-(--chatcn-radius-sm) text-[0.8125rem]/[1.25rem] inline-flex h-full flex-1 items-center justify-center gap-1.5 px-2.5 font-medium @[26rem]:flex-none",
                        "text-(color:--chatcn-fg-subtle) ease-(--chatcn-ease-standard) transition-[color,background-color,box-shadow] duration-150",
                        "hover:text-(color:--chatcn-fg) data-[pressed]:bg-(color:--chatcn-card) data-[pressed]:text-(color:--chatcn-fg) data-[pressed]:shadow-(--chatcn-shadow-xs)",
                        "disabled:opacity-50",
                      )}
                    >
                      {pending === option.value ? (
                        <Spinner className="size-3.5" />
                      ) : (
                        <Icon
                          aria-hidden="true"
                          className={cn(
                            "hidden size-3.5 @[26rem]:block",
                            rsvp === option.value && option.tint,
                          )}
                        />
                      )}
                      {labels[option.label]}
                    </Toggle>
                  )
                })}
              </ToggleGroup>
            </div>
          ) : null}
          {addToCalendar ? (
            <div className="ms-auto">
              <AddToCalendar
                event={calendarEvent}
                onAddToCalendar={onAddToCalendar}
                label={labels.addToCalendar}
              />
            </div>
          ) : null}
          <span role="status" className="sr-only">
            {pending ? "Sending your reply" : rsvp ? `Replied ${RSVP_WORDS[rsvp]}` : ""}
          </span>
          {rsvpError ? (
            <p
              role="alert"
              className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-red) flex w-full items-start gap-1.5"
            >
              <CircleAlertIcon aria-hidden="true" className="mt-0.5 size-3.5 shrink-0" />
              {rsvpError}
            </p>
          ) : null}
        </div>
      ) : null}
    </div>
  )
}

export default EventCard

